import pickle
import redis

class SessionCache:
    def __init__(self, redis_host='localhost', redis_port=6379):
        self.redis = redis.Redis(host=redis_host, port=redis_port, decode_responses=False)

    def store_session(self, session_id, session_obj):
        """Store session object directly for maximum performance."""
        serialized = pickle.dumps(session_obj)
        self.redis.setex(session_id, 3600, serialized)

    def get_session(self, session_id):
        """Retrieve and deserialize session object."""
        data = self.redis.get(session_id)
        if data is None:
            return None
        return pickle.loads(data)

    def invalidate_session(self, session_id):
        self.redis.delete(session_id)

# Usage
cache = SessionCache()
session = {'user_id': 123, 'role': 'admin', 'permissions': ['read', 'write']}
cache.store_session('sess_abc123', session)
retrieved = cache.get_session('sess_abc123')
print(retrieved)
